function applyFigmaTypography(container, screen) {
  const normalize = value => value.replace(/\s+/g, ' ').trim();
  const entries = screen === 'details' ? [...FigmaTypography.plans, ...FigmaTypography.details] : screen === 'plans' ? [...FigmaTypography.plans,...FigmaTypography.cart] : screen === 'captcha' ? FigmaTypography.captcha : FigmaTypography[screen] || [];
  const labels = new Map();
  for (const entry of entries) {
    const key = normalize(entry.text);
    if (!labels.has(key)) labels.set(key, []);
    labels.get(key).push(entry);
  }
  function artwork(text,element) {
    const choices=labels.get(normalize(text));
    if(!choices)return null;
    const style = getComputedStyle(element);
    const fontSize = parseFloat(style.fontSize);
    const bold = Number(style.fontWeight) >= 600;
    let entry = choices.slice().sort((first,second) => {
      const score = item => Math.abs(item.fontSize-fontSize) + (/(Bold|Heavy|Extra)/i.test(item.fontStyle) === bold ? 0 : 100);
      return score(first)-score(second);
    })[0];
    if(element.dataset.figmaType)entry=choices.find(item=>item.id===element.dataset.figmaType)||entry;
    else if(element.classList.contains('receipt-discount'))entry=choices.find(item=>item.id==='3911:23039')||entry;
    else if(element.matches('.receipt-line>span'))entry=choices.find(item=>item.id==='3911:23036')||entry;
    const image = document.createElement('img');
    image.src = 'assets/figma-desktop/' + entry.file;
    image.alt = normalize(entry.text);
    image.className = 'figma-type';
    image.width = entry.renderWidth;
    image.height = entry.renderHeight;
    return image;
  }
  for (const element of container.querySelectorAll('h1,h2,h3,h4,p,span,strong,s,u,button,label,li,.paywall-prompt')) {
    if(!element.isConnected)continue;
    if (element.closest('[data-native-art]') || element.classList.contains('figma-inline')) continue;
    if (!element.querySelector('img,input,button,a') && element.childElementCount<=3) {
      const text=element.innerText;
      const image=artwork(text,element);
      if(image){if(element.tagName==='BUTTON')element.setAttribute('aria-label',normalize(text));element.replaceChildren(image);continue;}
    }
    for(const child of Array.from(element.childNodes)) {
      if(child.nodeType!==Node.TEXT_NODE||!child.textContent.trim())continue;
      const image=artwork(child.textContent,element);
      if(!image)continue;
      const span=document.createElement('span');span.className='figma-inline';span.append(image);child.replaceWith(span);
    }
  }
  for(const input of container.querySelectorAll('input[placeholder]')) {
    const image=artwork(input.placeholder,input);
    if(!image)continue;
    image.classList.add('figma-placeholder');image.alt='';image.setAttribute('aria-hidden','true');
    const wrapper=document.createElement('span');wrapper.className='figma-input-shell';
    input.replaceWith(wrapper);wrapper.append(input,image);input.classList.add('vector-placeholder');
    const update=()=>{image.hidden=!!input.value;};input.addEventListener('input',update);update();
  }
}
